"""`.Eye Textures positioning`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Eye Textures positioning'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Eye Scaling', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'highlight up position', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'highlight down position', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'gradient positioning', 'NodeSocketVector', min_value=0.0, max_value=0.0)

    t.node('NodeFrame', 'Frame.003', props={
        'location': (88.4, 189.6),
        'width': 328.60446,
        'height': 272.40002,
        'label': 'Eye highlight scaling / position',
    })
    t.node('NodeFrame', 'Frame.006', props={
        'location': (86.0, -94.4),
        'width': 328.60443,
        'height': 270.0,
        'label': 'Eye highlight scaling / position',
    })
    t.node('NodeFrame', 'Frame.004', props={
        'location': (-270.0, 193.6),
        'width': 328.60443,
        'height': 408.76212,
        'label': 'Eye gradient scaling / position',
    })
    t.node('NodeFrame', 'Frame.005', props={
        'location': (-273.2, -92.8),
        'width': 328.60446,
        'height': 270.0,
        'label': 'Eye pupil scaling / position',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (448.1739, 41.461376),
        'width': 185.46573,
    })
    t.node('ShaderNodeGroup', 'Group', parent='Frame.003', props={
        'node_tree': lib.group('Scale Vector'),
        'location': (30.173225, -35.60269),
        'width': 268.60443,
    })
    t.node('ShaderNodeGroup', 'Group.001', parent='Frame.006', props={
        'node_tree': lib.group('Scale Vector'),
        'location': (30.175827, -35.884514),
        'width': 268.60443,
    })
    t.node('ShaderNodeGroup', 'eye_scale', parent='Frame.005', inputs={'Position Y': 24.0}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.933044, -36.11801),
        'width': 268.60443,
    })
    t.node('ShaderNodeGroup', 'Group.003', parent='Frame.004', props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.977661, -36.354034),
        'width': 268.60443,
    })
    t.node('NodeReroute', 'Reroute', props={
        'location': (-305.17096, -40.326767),
        'socket_idname': 'NodeSocketVector',
    })
    t.node('ShaderNodeTexCoord', 'Texture Coordinate', hide_outputs=('Generated', 'Normal', 'Object', 'Camera', 'Window', 'Reflection'), props={
        'location': (-467.76474, -5.1718264),
    })
    t.node('NodeReroute', 'Reroute.001', props={
        'location': (353.40674, -217.73096),
        'socket_idname': 'NodeSocketVector',
    })
    t.node('NodeReroute', 'Reroute.002', parent='Frame.004', props={
        'location': (54.70294, -373.76212),
        'socket_idname': 'NodeSocketVector',
    })

    t.link('Group', 'Coordinates', 'Group Output', 'highlight up position')
    t.link('Group.001', 'Coordinates', 'Group Output', 'highlight down position')
    t.link('Reroute.001', 'Output', 'Group Output', 'Eye Scaling')
    t.link('Group.003', 'Coordinates', 'Group Output', 'gradient positioning')
    t.link('Reroute', 'Output', 'Group.003', 'UV Map')
    t.link('Texture Coordinate', 'UV', 'Reroute', 'Input')
    t.link('Reroute', 'Output', 'eye_scale', 'UV Map')
    t.link('Reroute', 'Output', 'Group', 'UV Map')
    t.link('Reroute.002', 'Output', 'Group.001', 'UV Map')
    t.link('eye_scale', 'Coordinates', 'Reroute.001', 'Input')
    t.link('Reroute', 'Output', 'Reroute.002', 'Input')
    return t
